mapper.select:
SELECT id, record_date, amount, gross_amount, source_type, status, note, create_by, create_time, update_by, update_time FROM side_income_record
deleted = 0
AND source_type = #{dto.sourceType}
AND status = #{dto.status}
AND record_date >= #{dto.recordDateStart}
AND record_date <= #{dto.recordDateEnd}
AND note LIKE CONCAT('%', #{dto.note}, '%')
ORDER BY record_date DESC, id DESC
